"use client";

import { useState } from "react";
import { Dialog, DialogContent } from "@/components/ui/dialog"; // ✅ sadece olanları import ediyoruz
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Button } from "@/components/ui/button";

export default function TaskFormModal({ open, setOpen, onCreateTask }: any) {
  const [title, setTitle] = useState("");
  const [documentName, setDocumentName] = useState("");
  const [description, setDescription] = useState("");
  const [sprint, setSprint] = useState(1);
  const [hours, setHours] = useState(1);

  function handleSubmit() {
    const newTask = {
      type: "work_item",
      task: title,
      document: documentName,
      description,
      sprint,
      hours,
      created_by: "Tugce",
      created_at: Date.now(),
    };

    onCreateTask(newTask);
    setOpen(false);
  }

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogContent className="bg-[#0E153A]/90 border border-teal-400/30 shadow-2xl backdrop-blur-xl p-6 rounded-2xl">

        {/* ✅ Header yerine normal div */}
        <div className="mb-4">
          <h2 className="text-teal-300 text-2xl font-bold">
            Nieuwe Taak Aanmaken
          </h2>
        </div>

        {/* ✅ Form alanları */}
        <div className="flex flex-col gap-4 mt-4">

          <Input
            placeholder="Taak Titel"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            className="bg-[#0b1233] text-teal-200 border-teal-400/30"
          />

          <Input
            placeholder="Document Naam"
            value={documentName}
            onChange={(e) => setDocumentName(e.target.value)}
            className="bg-[#0b1233] text-teal-200 border-teal-400/30"
          />

          <Textarea
            placeholder="Beschrijving"
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            className="bg-[#0b1233] text-teal-200 border-teal-400/30"
          />

          <Input
            type="number"
            placeholder="Sprint Nummer"
            value={sprint}
            onChange={(e) => setSprint(+e.target.value)}
            className="bg-[#0b1233] text-teal-200 border-teal-400/30"
          />

          <Input
            type="number"
            placeholder="Uren"
            value={hours}
            onChange={(e) => setHours(+e.target.value)}
            className="bg-[#0b1233] text-teal-200 border-teal-400/30"
          />

          <Button
            onClick={handleSubmit}
            className="bg-gradient-to-r from-teal-400 to-fuchsia-400 text-black font-bold shadow-lg mt-3 hover:scale-105 transition"
          >
            Opslaan
          </Button>

        </div>
      </DialogContent>
    </Dialog>
  );
}